SELECT SUM("Generico_5"."InversionUS") AS "TEMP_TC___2622528870__0_",   CAST(EXTRACT(MONTH FROM "Generico_5"."FECHA") AS BIGINT) AS "mn_FECHA_ok",   SUM("Generico_5"."InversionUS") AS "sum_Calculation_0061002123102817_ok",   CAST(EXTRACT(YEAR FROM "Generico_5"."FECHA") AS BIGINT) AS "yr_FECHA_ok" FROM "Generico_5" WHERE ((CAST(EXTRACT(YEAR FROM "Generico_5"."FECHA") AS BIGINT) >= 2010) AND (CAST(EXTRACT(YEAR FROM "Generico_5"."FECHA") AS BIGINT) <= 2015) AND (((CAST(EXTRACT(MONTH FROM "Generico_5"."FECHA") AS BIGINT) >= 1) AND (CAST(EXTRACT(MONTH FROM "Generico_5"."FECHA") AS BIGINT) <= 7)) OR (CAST(EXTRACT(MONTH FROM "Generico_5"."FECHA") AS BIGINT) IS NULL)) AND ("Generico_5"."Anunciante" IN ('BANTRAB/TODOTICKET', 'TODOTICKET', 'TODOTICKET.COM'))) GROUP BY "mn_FECHA_ok",   "yr_FECHA_ok";
